/**
 * @file coupling_calculator.c
 * @brief Self-consistent calculation of electron-phonon coupling strength
 *
 * This program computes the renormalized coupling constant g as a function of
 * mass and frequency parameters by solving the coupled self-consistency equations
 * for the susceptibility and linewidth.
 *
 * The calculation includes:
 * - Lindhard susceptibility function (real and imaginary parts)
 * - Self-consistent phonon linewidth (GAMMA)
 * - Self-consistent coupling constant (G)
 *
 * Output: CSV-formatted coupling values for various parameter combinations
 */

#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <complex.h>

/* Physical constants */
static const double KB_EV = 8.617333262145179e-05;  /* Boltzmann constant [eV/K] */
static const double PI = 3.141592653589793;
static const double Q = PI;                          /* Momentum transfer */
static const double KF = PI / 2.0;                   /* Fermi momentum */

/* Numerical parameters */
#define MAX_ITER_GAMMA 40000000    /* Maximum iterations for GAMMA convergence */
#define MAX_ITER_G 100000000        /* Maximum iterations for G convergence */
#define TOL_GAMMA 0.01              /* Convergence tolerance for GAMMA */
#define TOL_G 0.1                   /* Convergence tolerance for G */

/* Default physical parameters */
#define TEMPERATURE 0.0             /* Temperature [K] for adiabatic susceptibility */
#define SIGMA 6000.0                /* Smearing parameter */
#define N_KPOINTS 1.0e5             /* Number of k-points for adiabatic susceptibility */
#define OMEGA_POINTS 2001           /* Number of frequency points */


/**
 * @brief Compute real part of Lindhard susceptibility (non-adiabatic) ad zero temperature
 *
 * @param a = 1/m* Mass parameter [1/me]
 * @param w Frequency [meV]
 * @param gamma Linewidth [meV]
 * @return Real part of susceptibility
 */
double susceptibility_real(double a, double w, double gamma) {
    double W = w / 1000.0;
    double ga = gamma / 1000.0;
    double numerator = pow(W * W + ga * ga, 2);
    double denom1 = pow(a * Q * Q + W, 2) + ga * ga;
    double denom2 = pow(a * Q * Q - W, 2) + ga * ga;

    return log(numerator / (denom1 * denom2)) / (2.0 * a * Q * 1000.0);
}


/**
 * @brief Compute imaginary part of Lindhard susceptibility
 *
 * @param a = 1/m* Mass parameter [1/me]
 * @param w Frequency [meV]
 * @param gamma Linewidth [meV]
 * @return Imaginary part of susceptibility
 */
double susceptibility_imag(double a, double w, double gamma) {
    double W = w / 1000.0;
    double ga = gamma / 1000.0;
    double term1 = 2.0 * atan(W / ga);
    double term2 = atan((-a * Q * Q + W) / ga);
    double term3 = atan((a * Q * Q + W) / ga);

    return -(term1 - term2 - term3) / (a * Q * 1000.0);
}


/**
 * @brief Compute dispersion relation ε(k)
 *
 * @param a = 1/m* Mass parameter [1/me]
 * @param k Wave vector
 * @return Energy ε(k)
 */
double dispersion(double a, double k) {
    return a * (k * k - KF * KF);
}


/**
 * @brief Compute shifted dispersion relation ε(k±q)
 *
 * @param a = 1/m* Mass parameter [1/me]
 * @param k Wave vector
 * @return Energy ε(k±q)
 */
double dispersion_shifted(double a, double k) {
    if (k >= 0) {
        return a * (pow(k - Q, 2) - KF * KF);
    } else {
        return a * (pow(k + Q, 2) - KF * KF);
    }
}


/**
 * @brief Fermi-Dirac distribution function
 *
 * @param energy Energy [eV]
 * @param temperature Temperature [K]
 * @return Occupation function
 */
double fermi_dirac(double energy, double temperature) {
    double kT = KB_EV * temperature;
    return 1.0 / (exp(energy / kT) + 1.0);
}


/**
 * @brief Compute adiabatic susceptibility via numerical integration
 *
 * @param a = 1/m* Mass parameter [1/me]
 * @param nK Number of k-points
 * @param w Frequency (complex)
 * @param T Temperature [K]
 * @return Complex susceptibility
 */
double complex susceptibility_adiabatic(double a, double nK, double complex w, double T) {
    double dK = 2.0 * PI / nK;
    double kT = KB_EV * T;
    double complex ws = w / 1000.0;
    double eta = kT / 100.0;
    double complex X_val = 0.0;

    for (int j = 0; j < nK; j++) {
        double K = -PI + j * dK;
        double ek = dispersion(a, K);
        double ekq = dispersion_shifted(a, K);

        double complex chi = (fermi_dirac(ekq, T) - fermi_dirac(ek, T)) /
                            (ekq - ek - ws - eta * I);
        X_val += chi;
    }

    return X_val * dK / 1000.0;
}


/**
 * @brief Self-consistently compute phonon linewidth GAMMA
 *
 * Iteratively solves: gamma = -(omega/Omega) * g^2 * Im[X(Omega, gamma)]
 *
 * @param gamma Initial guess for linewidth
 * @param g EPC matrix element
 * @param a Mass parameter
 * @param omega High temperature phonon frequency [meV]
 * @param Omega Low temperature phonon frequency [meV]
 * @return Converged linewidth [meV]
 */
double compute_linewidth(double gamma, double g, double a, double omega, double Omega) {
    double prefactor = -omega / Omega * g * g;
    double last_gamma = gamma;

    for (int i = 0; i < MAX_ITER_GAMMA; i++) {
        double X_im = susceptibility_imag(a, Omega, gamma);

        if (isnan(X_im)) {
            return NAN;
        }

        gamma = prefactor * X_im;

        if (fabs(gamma - last_gamma) <= TOL_GAMMA || isnan(gamma)) {
            return gamma;
        }

        last_gamma = gamma;
    }

    return NAN;  /* Failed to converge */
}


/**
 * @brief Self-consistently compute EPC matrix element 
 *
 * Solves the self-consistency equation by finding the root of:
 * A*g^4 + B*g^2 + C = 0, where coefficients depend on susceptibility
 *
 * @param gamma Phonon linewidth
 * @param g0 Initial guess for EPC strenght
 * @param a = 1/m* Mass parameter [1/me]
 * @param nK Number of k-points
 * @param omega High temperature phonon frequency
 * @param Omega Low temperature phonon frequency
 * @param T Temperature [K]
 * @param sigma Smearing parameter [K]
 * @return Converged g [meV]
 */
double compute_coupling(double gamma, double g0, double a, double nK,
                       double omega, double Omega, double T, double sigma) {
    double tmp_g = g0;
    double last_g = tmp_g;

    /* Compute adiabatic susceptibility (real part at w=0 and T=sigma) */
    double X_reA = creal(susceptibility_adiabatic(a, nK, 0.0, sigma));

    for (int i = 0; i < MAX_ITER_G; i++) {
        /* Update linewidth with current coupling */
        gamma = compute_linewidth(gamma, tmp_g, a, omega, Omega);

        /* Compute non-adiabatic susceptibilities */
        double X_reNA = susceptibility_real(a, Omega, gamma);
        double X_im = susceptibility_imag(a, Omega, gamma);

        /* Solve quadratic equation: A*g^4 + B*g^2 + C = 0 */
        double A = pow(omega, 2) * pow(X_im, 2) / pow(Omega, 2);
        double B = 2.0 * omega * (X_reNA - X_reA);
        double C = omega * omega - Omega * Omega;

        /* Use quadratic formula for g^2 */
        double discriminant = B * B - 4.0 * A * C;
        if (discriminant < 0) {
            return NAN;  /* No real solution */
        }

        double sol2 = (-B - sqrt(discriminant)) / (2.0 * A);

        if (sol2 < 0) {
            return NAN;  /* Negative g^2 is unphysical */
        }

        tmp_g = sqrt(sol2);

        /* Check convergence */
        if (fabs(tmp_g - last_g) < TOL_G || isnan(tmp_g)) {
            return tmp_g;
        }

        last_g = tmp_g;
    }

    return NAN;  /* Failed to converge */
}


/**
 * @brief Main program: compute g for parameter scan
 *
 * Outputs coupling values for combinations of mass and frequency parameters
 * in CSV format.
 */
int main(void) {
    /* Parameter arrays */
    double mass_params[5] = {0.2, 0.5, 1.0, 2.0, 5.0};
    double freq_params[5] = {10.0, 50.0, 100.0, 150.0, 200.0};

    /* Frequency scan array */
    double omega_scan[OMEGA_POINTS];

    /* Initial guesses */
    double gamma = 1.0;
    double g = 100.0;

    /* Loop over mass parameters */
    for (int k = 0; k < 5; k++) {
        double mass = mass_params[k];

        /* Loop over frequency parameters */
        for (int j = 0; j < 5; j++) {
            double freq = freq_params[j];

            /* Generate frequency scan */
            for (int i = 0; i < OMEGA_POINTS; i++) {
                omega_scan[i] = freq * i / (OMEGA_POINTS - 1.0);
            }

            /* Scan in reverse order */
            for (int i = OMEGA_POINTS - 1; i >= 0; i--) {
                gamma = compute_linewidth(gamma, g, mass, freq, omega_scan[i]);
                g = compute_coupling(gamma, g, mass, N_KPOINTS, freq,
                                    omega_scan[i], TEMPERATURE, SIGMA);

                /* Output coupling value */
                if (i == 0) {
                    printf("%.5f\n ", g);
                } else {
                    printf("%.5f, ", g);
                }

                /* Reset to defaults if convergence failed */
                if (isnan(gamma)) gamma = 1.0;
                if (isnan(g)) g = 100.0;
            }

            fflush(stdout);
        }
    }

    return EXIT_SUCCESS;
}
